function validate(input) {
  const [{ Spotify = [] }] = input;
  const ids = new Set();
  for (const [id, track, artist] of Spotify) {
    if (id === null || track === null || artist === null) return 'id, track_name and artist are required.';
    if (ids.has(id)) return `id ${id} appears twice in Spotify.`;
    ids.add(id);
  }
  return null;
}

