function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const tracks = ['Happier', 'Shape of You', 'Hello', "I'm the One", 'Young Dumb & Broke', 'Chandelier', 'Halo'];
  let artists;
  if (size === 'small') {
    // A few artists, so counts collide and the alphabetical tie-break matters.
    const pool = ['Sia', 'Ed Sheeran', 'DJ Khalid', 'Adele', 'Beyonce', 'Zara Larsson'];
    artists = pool.slice(0, 1 + pick(pool.length));
  } else {
    const first = ['Ada', 'Ben', 'Cleo', 'Dua', 'Eli', 'Finn', 'Gia', 'Hal', 'Ivy', 'Jo', 'Kai', 'Lia'];
    const last = ['Moss', 'Nash', 'Ortiz', 'Park', 'Quinn', 'Reyes', 'Stone', 'Tate', 'Vale', 'Wren'];
    artists = first.flatMap(a => last.map(b => `${a} ${b}`));
  }
  const count = size === 'small' ? pick(9) : 2000;
  const ids = new Set();
  while (ids.size < count) ids.add(1 + pick(size === 'small' ? 50 : 1000000));
  const Spotify = [...ids].map(id => [id, tracks[pick(tracks.length)], artists[pick(artists.length)]]);
  return [{ Spotify }];
}
